const C={ink:'#233e4b',line:'#6b8f9f',pale:'#f1f7fa',liquid:'#d5e6ef',solid:'#9bb8c5',heat:'#d9a764'};
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const tx=(x,y,s,size=17)=>`<text x="${x}" y="${y}" text-anchor="middle" font-family="Arial,sans-serif" font-size="${size}" fill="${C.ink}">${esc(s)}</text>`;
const line=(d,c=C.line,w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const box=(x,y,w,h,fill=C.pale)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="11" fill="${fill}" stroke="${C.line}" stroke-width="1.6"/>`;
const arrow=(x,y,a=0)=>`<g transform="translate(${x} ${y}) rotate(${a})">${line('M-23 0H23M15 -7L23 0L15 7',C.line,2.5)}</g>`;
function wrap(s,max=71){let rows=[],row='';for(const w of String(s).split(/\s+/)){if((row+' '+w).length>max){rows.push(row);row=w;}else row+=(row?' ':'')+w;}if(row)rows.push(row);return rows;}
const title=s=>wrap(s,46).map((t,i)=>tx(300,27+i*24,t,20)).join('');
const note=s=>wrap(s).map((t,i)=>tx(300,345+i*17,t,13)).join('');
const panel=(x,y,w,rows)=>box(x,y,w,rows.length*29+23)+rows.map((s,i)=>tx(x+w/2,y+29+i*29,s,16)).join('');
function beaker(x,y,{powder=false,label='',stir=false}={}){return `<path d="M${x-56} ${y-65}V${y+47}Q${x-56} ${y+61} ${x-43} ${y+61}H${x+43}Q${x+56} ${y+61} ${x+56} ${y+47}V${y-65}" fill="none" stroke="${C.line}" stroke-width="2.5"/>`+(powder?`<path d="M${x-44} ${y+48}Q${x-24} ${y+20} ${x} ${y+36}Q${x+20} ${y+10} ${x+44} ${y+48}Z" fill="${C.solid}"/>`:`<path d="M${x-53} ${y-15}H${x+53}V${y+44}Q${x+53} ${y+58} ${x+40} ${y+58}H${x-40}Q${x-53} ${y+58} ${x-53} ${y+44}Z" fill="${C.liquid}"/>`)+(stir?line(`M${x-18} ${y+37}H${x+18}`,C.ink,6):'')+tx(x,y+88,label,17);}
function grains(x,y,bulk=false){return bulk?box(x-48,y-25,93,51,C.solid):[[-35,-15],[0,-22],[36,-8],[-16,22],[22,27]].map(([a,b])=>`<circle cx="${x+a}" cy="${y+b}" r="12" fill="${C.solid}" stroke="${C.line}"/>`).join('');}
function oven(inside,rows,label){return box(49,98,280,215,'#dfe7eb')+box(75,123,226,164,'#fcf1df')+line('M93 144Q83 158 93 172Q103 186 93 200',C.heat,3)+inside+tx(188,303,label,14)+panel(363,130,213,rows);}
function stage(o,r){let art='',notes='Conditions retain their source scope; all apparatus geometry is illustrative.';const id=o.id,rid=r.record_id,variant=/anneal-(600|700|900|1000)$/.test(rid);
 if(id==='dissolve-a'){art=panel(20,92,214,['La₂O₃ · Yb₂O₃ · Er₂O₃','Diluted nitric acid'])+arrow(288,182)+beaker(434,173,{label:'Solution A precursor'});notes=variant?'Shared solution A preparation; individual comparison-batch charges are not restated. Acid concentration, volume and exact solution speciation remain unreported.':'All three oxide charges are retained in the record. Nitric acid concentration and volume are unreported; the diagram does not assert exact nitrate speciation.';}
 else if(id==='dry-a'){art=beaker(198,173,{powder:true,label:''})+box(128,253,140,30,'#eddbbb')+tx(198,309,'Rare-earth residue',17)+line('M168 147Q159 132 168 117M195 147Q186 132 195 117M222 147Q213 132 222 117',C.heat)+panel(365,125,205,['Warm to dryness','Remove excess acid','Temperature unknown']);notes='Warming removes unreacted nitric acid. Heating apparatus is schematic; time, temperature and the residue’s detailed hydration/speciation are not specified.';}
 else if(id==='redissolve-a'){art=panel(20,117,198,['Deionized water','30 mL'])+arrow(265,179)+beaker(418,178,{label:'Redissolved residue'});notes='Thirty millilitres is added water, not a measured final solution volume. No exact molarity or acid-free composition is reconstructed.';}
 else if(id==='stir-a'||id==='stir-b'){art=beaker(188,167,{stir:true,label:id==='stir-a'?'Solution A':'Solution B'})+box(113,259,150,30)+panel(353,119,216,['Stir 1 h','Room temperature','No numeric temperature']);notes='A and B are separately stirred for one hour at room temperature. Stirrer geometry is illustrative; speed and numeric temperature are not reported.';}
 else if(id==='dissolve-b'){art=panel(18,99,214,['(NH₄)₂MoO₄',variant?'Charges not restated':'1.961 g / 9.37 mmol',variant?'Reference stock conflict':'Reported conflict'])+arrow(278,180)+beaker(428,174,{label:'30 mL deionized water'});notes=variant?'Shared solution B preparation; individual comparison-batch charges are not restated. The reference stock has a mass/mole conflict; no corrected dose or molarity is supplied.':'The mass and mole amount printed for ammonium molybdate are inconsistent. Both remain visible; no corrected dose, final solution volume or molarity is supplied.';}
 else if(id==='combine'){art=beaker(161,174,{label:'Solution B'})+arrow(273,170)+beaker(416,174,{stir:true,label:'Solution A + suspension'})+panel(274,73,275,['20–30 drops per minute']);notes='Add B to A drop by drop with vigorous stirring. Drop volume and total addition duration are unreported; drop rate is not converted to a volume flow rate.';}
 else if(id==='stir-suspension'){art=beaker(198,166,{stir:true,label:'Formed suspension'})+box(123,258,150,30)+panel(357,127,211,['Continuous stirring','20 min','Temperature unreported']);notes='This twenty-minute suspension stage follows dropwise addition. The source does not state a separate stirring speed, pressure or numeric reaction temperature.';}
 else if(id==='transfer'){art=beaker(146,171,{label:'Suspension'})+arrow(276,174)+box(364,113,130,134,'#e6edf1')+box(354,99,150,23,'#c2d1d9')+tx(430,279,'100 mL Teflon vessel',16);notes='Transfer the suspension to the 100 mL Teflon vessel, cap it and place it in the RD-100 autoclave. Vessel capacity is not a measured reaction fill volume.';}
 else if(id==='hydrothermal'){art=box(83,110,189,175,'#cedae2')+box(115,133,125,122,'#edf3f5')+box(76,94,202,28,'#b5c6d0')+line('M118 274H239',C.heat,7)+tx(176,310,'Capped autoclave',17)+panel(350,123,216,['180 °C · 1 h','RD-100 / Teflon vessel','Pressure not reported']);notes='Hydrothermal heating is reported at 180 °C for one hour. Pressure, ramp and cooling before centrifugation are missing; do not infer a numeric autogenous pressure.';}
 else if(id==='centrifuge'){art=box(60,109,233,181,'#e1eaf0')+`<circle cx="176" cy="200" r="58" fill="none" stroke="${C.line}" stroke-width="3"/>`+line('M135 159L217 241M217 159L135 241')+arrow(335,189)+`<path d="M421 116V228L444 272L467 228V116" fill="${C.liquid}" stroke="${C.line}" stroke-width="2"/><path d="M431 249L444 272L457 249Z" fill="${C.solid}"/>`+tx(445,308,'Retain precipitate',17)+tx(176,96,'6000 rpm · 10 min',18);notes='The recovered precipitate continues to washing. The source gives rpm and duration, without rotor radius or relative centrifugal force; supernatant is a separate fraction.';}
 else if(id==='wash'){art=panel(18,109,211,['Deionized water','Two washes','Volumes unreported'])+arrow(279,174)+beaker(424,171,{powder:true,label:'Washed precipitate'});notes='Wash the recovered precipitate twice with deionized water. Wash volume and separation conditions for each wash are not specified; the initial centrifuge settings are not silently reused.';}
 else if(id==='dry'){art=box(79,219,239,31,'#e1eaf0')+grains(198,213)+line('M146 142Q170 124 194 143M212 142Q235 124 259 143')+panel(356,119,217,['Air drying','White powder','Time / temperature unknown']);notes='The hydrothermal precipitate is dried in air before annealing. The white powder is a preparative intermediate; no drying oven temperature or duration is supplied.';}
 else if(['ramp','anneal','cool'].includes(id)){
  const t=Number(rid.split('-').at(-1)),main=t===800;
  if(id==='ramp'){art=oven(grains(193,214,false),['Heat toward '+t+' °C',main?'20 °C per minute':'Ramp not restated','Atmosphere unreported'],'Powder heat treatment');notes=main?'The explicit 800 °C preparation uses a 20 °C/min heating ramp. No nano-annealing atmosphere is specified; air drying does not establish an air furnace.':'The temperature-series endpoint is reported, but a 20 °C/min ramp is only explicit in the 800 °C preparation. Do not convert that rate to a separately measured variant setting.';}
  if(id==='anneal'){art=oven(grains(193,214,t===1000),[t+' °C · 5 h',t===900?'Aggregation reported':t===1000?'Bulk form reported':'Annealed phosphor','Atmosphere unreported'],'Thermal annealing');notes='Each temperature is a separate reported comparison condition, not proof of an independently documented precursor batch. Grain geometry is explanatory; no size is interpolated from temperature.';}
  if(id==='cool'){art=grains(153,213,t===1000)+arrow(282,203)+grains(438,213,t===1000)+panel(283,93,288,[main?'Natural cooling to room temperature':'Cooling framework inherited / unverified']);notes=main?'Natural cooling to room temperature follows the reported 800 °C, five-hour anneal. No cooling rate or numeric final temperature is supplied.':'The general 800 °C method describes natural cooling; the comparison condition does not restate its cooling history. Preserve the inheritance limit and missing rates.';}
 }
 else if(rid.endsWith('bulk')){
  if(id==='mix'){art=panel(22,105,244,['La₂O₃ · MoO₃ · Yb₂O₃ · Er₂O₃','La:Yb:Er = 77:20:3','Absolute charges unreported'])+arrow(304,187)+beaker(448,176,{powder:true,label:'Solid precursor mixture'});notes='This is a distinct solid-state bulk comparator. The reported metal ratio does not supply total batch mass or a molybdenum ratio; no hydrothermal quantities are inherited.';}
  if(id==='press'){art=box(148,102,142,30,'#c4d5de')+arrow(218,166,90)+box(140,216,160,40,C.solid)+line('M112 270H326',C.ink,5)+panel(373,113,200,['Press into a pellet','Pressure unknown','Dimensions unknown']);notes='Pellet pressing is reported without force, pressure, tool dimensions or duration. The press diagram conveys compression only.';}
  if(id==='fire'){art=oven(box(136,219,110,29,C.solid),['1200 °C · 5 h','Air','Ramp not reported'],'Fire the bulk pellet');notes='Bulk firing is explicitly in air at 1200 °C for five hours. This atmosphere belongs to the bulk route; it is not an assumed nanocrystal-annealing atmosphere.';}
 }
 else if(rid.endsWith('bulk-grinding')){
  if(id==='grind'){art=box(93,152,110,82,C.solid)+arrow(281,194)+grains(444,214)+panel(332,80,242,['Grinding settings unreported']);notes='The authors report grinding a bulk sample to a fine powder. No apparatus, particle-size result, grinding duration or nanoscale size is specified.';}
  if(id==='compare'){art=panel(23,110,224,['Bulk powder before grinding'])+arrow(296,176)+panel(351,105,222,['Ground bulk powder','No optical improvement']);notes='The qualitative grinding control supports the authors’ discussion. No original paired spectra or exact intensity change are supplied; lower emission is not a failed synthesis label.';}
 }
 else if(rid.endsWith('xrd')){
  if(id==='acquire'){art=panel(23,105,148,['X-ray beam'])+arrow(216,176,25)+box(277,215,95,25,C.solid)+arrow(405,176,-25)+panel(442,91,136,['D8 advance','Diffraction']);notes='XRD Figure 1 is assigned to the 800 °C, five-hour sample. The paper reports tetragonal phase with a little second phase; no phase-pure refinement or atomic coordinates are supplied.';}
  if(id==='scherrer'){art=panel(25,103,222,['Peak at 2θ=28.053°','B₁=0.186°; B₀=0.104°'])+arrow(297,178)+panel(352,104,217,['Scherrer estimate','52.5 nm']);notes='The reported crystallite size is an author-derived XRD estimate, distinct from TEM particle diameter and the particle-analyzer distribution. Missing wavelength and shape factor are not reconstructed.';}
 }
 else if(rid.endsWith('tem')){art=panel(22,105,195,id==='compare'?['Before annealing','Figure 2a · 300 nm bar']:['Hitachi TEM','Settings unreported'])+arrow(282,184)+panel(346,105,230,id==='compare'?['800 °C / 5 h specimen','Figure 2b · 100 nm bar']:['Original micrographs','Preserve sample states']);notes='The two TEM panels show different preparation states and scale bars. Source descriptions of 40–60 nm particles and unchanged size at 800 °C do not establish identical imaged particles.';}
 else if(rid.endsWith('particle-size')){art=panel(22,107,227,['BI-90Plus size analyzer','Specimen dispersion unknown'])+arrow(301,185)+panel(362,104,213,['Source histogram','Mean about 53 nm']);notes='Figure 3 has an intensity axis. Preserve the source 45–65 nm majority range and mean separately from TEM and Scherrer values; do not relabel it as a particle-count histogram.';}
 else if(rid.endsWith('downconversion')||rid.endsWith('upconversion')){
  const up=rid.endsWith('upconversion');
  if(id==='excite'){art=panel(21,102,203,up?['External 980 nm laser','50 mW source rating']:['374 nm excitation','LS-50B'])+arrow(282,176)+grains(433,188);notes=up?'The external 980 nm laser replaces the instrument xenon source and uses an optical fiber. The 50 mW specification is not a measured sample irradiance or photon dose.':'Down-conversion is excited at 374 nm. The excitation spectrum in Figure 4a is distinct from the emission spectrum; source slit widths and collection geometry are incomplete.';}
  if(id==='acquire'){art=grains(137,199)+arrow(261,189)+panel(327,106,246,['LS-50B spectrophotometer',up?'519 / 541 /653 nm':'525 / 549 nm','Front-surface accessory']);notes='Only source-reported spectral peaks are annotated. Original spectra retain arbitrary-intensity axes; no calibrated quantum yield or reconstructed dense curve is supplied.';}
  if(id==='compare'){art=panel(22,103,230,['Hydrothermal nanocrystals','Green-dominant emission'])+tx(297,179,'↔',28)+panel(351,103,227,['Solid-state bulk comparator','Red-dominant emission']);notes='Figure 10 compares different preparations. The authors attribute differences to size and surface effects; this is not a controlled measurement of quantum yield or lifetime.';}
 }
 else if(rid.endsWith('near-ir')){art=panel(23,103,237,['PE SYSTEM2000 FTIR','Quartz beam splitter'])+arrow(300,179)+panel(352,101,224,['9000–11000 cm⁻¹','Near-IR absorption']);notes='The printed frequency axis uses inverse centimetres, a wavenumber unit. The absorption center is about 10238 cm⁻¹ (976 nm); no unreported scan resolution is added.';}
 else if(rid.endsWith('erbium-series')){art=panel(24,94,237,['Er³⁺ mole-fraction series','1,2,3,4,5,7%'])+arrow(306,177)+panel(359,112,215,['Source comparison','Adjusted charges unknown']);notes='Only six plotted composition markers are present. A 1–7% range does not establish a 6% data point, fixed Yb fraction, compensating La dose or exact per-variant recipes.';}
 else if(rid.endsWith('power-response')){
  if(id==='sweep'){art=panel(20,107,217,['980 nm excitation','Vary source intensity'])+arrow(291,182)+panel(358,108,215,['Three emission bands','No sample-area value']);notes='The source relates emission to excitation intensity on logarithmic axes. No beam area, full numeric sweep or raw point array is given; the source 50 mW rating is not every sweep setting.';}
  if(id==='fit'){art=panel(21,106,233,['ln(Iup) versus ln(Iexc)','Fit each band'])+arrow(303,185)+panel(364,104,214,['2.2024 /1.8853 /2.0907','Source plotted slopes']);notes='Rounded prose slopes 2.20/1.89/2.09 remain separate. Figure 8 caption says 520 nm while its legend and body use 519 nm. Approximately two-photon behavior is author interpretation.';}
 }
 return art?{art,notes,heading:o.label}:null;
}
export function buildYi2002Scene(o,r){if(r?.lineage?.source_group!=='yi2002'||!r.record_id?.startsWith('yi-2002-'))return null;const s=stage(o,r);if(!s)return null;return{kind:r.record_id+'-'+o.id,svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 420" role="img" aria-label="${esc(o.label)} — explanatory apparatus" style="width:100%;height:auto"><title>${esc(o.label)}</title><desc>Source-specific hydrothermal, thermal and analytical stage. All apparatus geometry, shapes and colors are illustrative; no measured spectrum, micrograph or atomic structure is simulated.</desc>${title(s.heading)}${s.art}${note(s.notes)}</svg>`,caption:'Source-specific scientific schematic. Shared preparation and comparison specimens retain their own evidence scope; dimensions and colors are illustrative.'};}
export function createYi2002Art(o,r){const s=buildYi2002Scene(o,r);if(!s)return null;const d=document.createElement('div');d.className='protocol-art protocol-art-yi2002';d.dataset.scene='yi2002-'+s.kind;d.style.height='auto';d.innerHTML=s.svg;return d;}
